function escEnd(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
if(!obterTokenCliente())location.href='login.html';(async()=>{const el=document.getElementById('enderecos-real');try{const rows=await apiFetch('/auth/clientes/enderecos');el.innerHTML=rows.length?rows.map(a=>`<div class="cartao-endereco"><strong>${escEnd(a.rotulo||'Morada')}</strong>${escEnd(a.linha1)}${a.linha2?'<br>'+escEnd(a.linha2):''}<br>${escEnd(a.codigo_postal||'')} ${escEnd(a.cidade)}<br>${escEnd(a.pais)}${a.predefinido?' · Predefinida':''}<br><button type="button" onclick="removerEndereco(${a.id})">Remover</button></div>`).join(''):'<p class="estado-vazio">Ainda não existem endereços guardados.</p>';}catch(e){el.textContent=e.message||'Não foi possível carregar as moradas.';}})();document.getElementById('btn-novo-end').onclick=()=>{document.getElementById('form-endereco').style.display='block'};
document.getElementById('form-endereco').addEventListener('submit',async e=>{e.preventDefault();const v=id=>document.getElementById(id).value.trim();try{await apiFetch('/auth/clientes/enderecos',{method:'POST',body:JSON.stringify({rotulo:v('en-rotulo'),linha1:v('en-linha1'),linha2:v('en-linha2'),cidade:v('en-cidade'),codigoPostal:v('en-cp'),pais:v('en-pais'),telefone:v('en-tel'),predefinido:document.getElementById('en-pred').checked})});location.reload()}catch(err){document.getElementById('en-msg').textContent=err.message}});
async function removerEndereco(id){if(!confirm('Remover este endereço?'))return;try{await apiFetch('/auth/clientes/enderecos/'+id,{method:'DELETE'});location.reload()}catch(e){alert(e.message)}}
